from series import *
start('استاد هاشمی','hashemi',[('مفهوم و سنجش','طیف، مهار، کشتن و حساسیت'),('دیواره و غشا','خانواده‌ها و تفاوت هدف‌ها'),('پروتئین و مادهٔ ژنتیکی','ریبوزوم، اسید نوکلئیک و فولات'),('مقاومت و کاربرد در جزوه','دندان‌پزشکی و سه موضوع گوارشی')])
A(1,'واژه‌های پایه و منطق انتخاب هدف',[3,4,5,6], 'برای شناخت یک آنتی‌بیوتیک، باید هدف اثر، طیف فعالیت و توان مهار یا کشتن باکتری را بدانیم. وسیع‌تر بودن طیف، به‌تنهایی به معنای انتخاب مناسب‌تر نیست.',[
 ['طیف','محدودهٔ میکروب‌هایی که دارو بر آن‌ها فعالیت دارد؛ وسیع‌بودن لزوماً مناسب‌تر بودن نیست.'],['باکتریواستاتیک / باکتریسیدال','مهار رشد در برابر اثر کشنده در تعریف درسی'],['حداقل غلظت مهارکننده / کشنده (MIC / MBC)','MIC کمترین غلظتی است که رشد قابل مشاهده را مهار می‌کند؛ MBC کمترین غلظت دارای اثر کشنده در آزمون است. مهار رشد و مرگ باکتری یک نتیجه نیستند.'],['سینرژی / آنتاگونیسم','اثر ترکیبی بیشتر در برابر کمتر از انتظار؛ اثر دو دارو می‌تواند هم‌افزا، مستقل یا کاهنده باشد.'],['MDR، XDR، PDR','به ترتیب مقاومت چندگانه، بسیار گسترده و فراگیر در متن؛ تعریف دقیق هر یک به رده‌ها و زمینه وابسته است.'],['تاریخچه','مشاهدهٔ مهار استاف کنار کپک در توضیح فلمینگ؛ تاریخ کشف با کاربرد بالینی یکی نیست.'],['سمیت انتخابی','تفاوت هدف باکتری و میزبان مهم است؛ MTT در متن برای ارزیابی اثر سمی ماده روی سلول مطرح شده، نه اثبات بی‌خطری مطلق.'] ],
 'مهار با کشتن فرق دارد؛ طیف با قدرت و ترکیب با سود قطعی فرق دارد.',
 [('MIC و MBC چه تفاوتی دارند؟','MIC مهار رشد قابل مشاهده و MBC اثر کشنده را می‌سنجد. این دو عدد معنای یکسانی ندارند و مقدار مصرف دارو مستقیماً از عدد MIC به‌دست نمی‌آید.',['مهار','کشتن','محدودیت']),('چرا ترکیب دارو همیشه بهتر نیست؟','اثر ترکیب می‌تواند هم‌افزا یا اثر آنتاگونیستی داشته باشد؛ هدف، عامل و سمیت هم باید سنجیده شوند.',['سینرژی','آنتاگونیسم','زمینه'])])
A(1,'آنتی‌بیوگرام، MIC و نقشهٔ هدف‌ها',[6,7], 'شناسایی باکتری و سنجش حساسیت آن دو مرحلهٔ متفاوت‌اند. آنتی‌بیوگرام نشان می‌دهد جدایهٔ شناسایی‌شده در برابر داروها چه پاسخی دارد و نتیجه با معیارهای استاندارد تفسیر می‌شود.',[
 ['شناسایی و حساسیت','اول شناخت عامل، سپس تفسیر پاسخ به دارو؛ CLSI و EUCAST در متن نام استانداردهای تفسیرند، نه نسخهٔ ثابت یک عفونت.'],['دیسک','ناحیهٔ مهار و تفسیر ردهٔ حساسیت؛ اندازهٔ خام بدون معیار، حکم نهایی نیست.'],['MIC','گزارش عددیِ مهار؛ شکل نوارِ صفحهٔ ۷ برای ارتباط مرز رشد و عدد آمده است.'],['هدف‌های شکل','دیواره؛ غشا؛ ریبوزوم ۳۰S و ۵۰S؛ همانندسازی DNA؛ رونویسی RNA؛ متابولیسم فولات'],['نمونه‌های تکمیلی شکل','فوسفومایسین/سیکلوسرین/باسیتراسین و وانکومایسین برای دیواره؛ پلی‌میکسین برای غشا؛ لاینزولید و استرپتوگرامین برای پروتئین؛ ریفامپین برای RNA'],['خودکار','Vitek فقط نام سامانهٔ نام‌برده در جزوه است؛ نتیجه همچنان نیاز به تفسیر دارد.'] ],
 'عامل کیست؟ به چه پاسخ می‌دهد؟ آزمون کدام پایان را اندازه گرفته است؟',
 [('چرا هاله و MIC یک گزارش نیستند؟','قطر هالهٔ مهار با معیار استاندارد مقایسه می‌شود تا ردهٔ حساسیت مشخص شود؛ MIC کمترین غلظت مهارکنندهٔ رشد را به‌صورت عددی گزارش می‌کند. هیچ‌کدام به‌تنهایی مقدار مصرف بیمار را تعیین نمی‌کنند.',['هاله','غلظت','تفسیر']),('هدف‌های اصلی دارو را نام ببرید.','دیواره، غشا، پروتئین در دو زیرواحد، DNA، RNA و مسیر متابولیک مانند فولات.',['ساختار','اطلاعات','متابولیسم'])])
A(2,'بتالاکتام و مهارکنندهٔ بتالاکتاماز',[3,7,8], 'بتالاکتام‌ها ساخت دیواره را مهار می‌کنند؛ بتالاکتاماز می‌تواند دارو را تخریب کند و مهارکنندهٔ بتالاکتاماز، بعضی از این آنزیم‌ها را مهار می‌کند. شناخت نقش هر جزء، ترکیب‌های دارویی را روشن می‌کند.',[
 ['حلقهٔ بتالاکتام','پنی‌سیلین‌ها، سفالوسپورین/سفامایسین، کارباپنم و مونوباکتام در خانوادهٔ ساختاری متن‌اند.'],['بتالاکتاماز','آنزیم هیدرولیزکنندهٔ حلقه؛ تغییر ساختار دارو با کاهش فعالیت مرتبط می‌شود.'],['G و V','G تزریقی و حساس‌تر به اسید؛ V مقاوم‌تر به اسید و خوراکی در مقایسهٔ درسی'],['مقاوم به پنی‌سیلیناز','متی‌سیلین و اگزاسیلین در مثال استاف؛ مقاومت به یک آنزیم برابر فعالیت علیه همهٔ مکانیسم‌ها نیست.'],['دارو و ترکیب','آموکسی‌سیلین در برابر آموکسی‌کلاو؛ پیپراسیلین در برابر پیپراسیلین–تازوباکتام؛ جزء مهارکننده از داروی همراه در برابر بعضی آنزیم‌های تخریب‌کننده محافظت می‌کند.'],['نام‌های مهارکننده','کلاوولانات، سولباکتام و تازوباکتام؛ در نام ترکیب، آنتی‌بیوتیک را از جزء مهارکنندهٔ آنزیم جدا کن.'] ],
 'بتالاکتام ساخت دیواره را مهار می‌کند؛ بتالاکتاماز دارو را تخریب می‌کند؛ مهارکننده، بعضی بتالاکتامازها را مهار می‌کند.',
 [('بتالاکتاماز و مهارکننده چه تفاوتی دارند؟','آنزیم دارو را غیرفعال می‌کند؛ مهارکننده بخشی از این آنزیم‌ها را هدف می‌گیرد تا داروی همراه فرصت اثر داشته باشد. همهٔ آنزیم‌ها یکسان نیستند.',['آنزیم','مهارکننده','داروی همراه']),('آموکسی‌سیلین و آموکسی‌کلاو چگونه فرق دارند؟','دومی ترکیب آموکسی‌سیلین با کلاوولانات است؛ افزودن مهارکننده را با تغییر همهٔ ویژگی‌های خود آنتی‌بیوتیک یکی نمی‌کنیم.',['دو جزء','نقش هر جزء'])])
A(2,'سفالوسپورین، کارباپنم و جدول طیف',[9,10], 'سفالوسپورین‌ها و کارباپنم‌ها هر دو بتالاکتام‌اند، اما اعضای هر خانواده طیف یکسانی ندارند. نام دارو باید همراه با ویژگی اختصاصی آن خوانده شود.',[
 ['سفالوسپورین','مشتقات طبیعی/سنتزی با اثر بر دیواره؛ متن از نسل‌ها سخن می‌گوید ولی جدول بر محور طیف نوشته شده است.'],['محدود در جدول','سفالکسین، سفالوتین، سفاپیرین، سفازولین و سفرادین؛ گرم مثبت و بخشی از منفی‌ها'],['گسترده در جدول','سفاکلور و سفوروکسیم؛ فعالیت بیشتر در بعضی گرم منفی‌ها در شرح منبع'],['سفامایسین','سفوتتان و سفوکسیتین؛ حساسیت کمتر به برخی بتالاکتامازها در متن'],['وسیع در جدول','سفیکسیم، سفوتاکسیم، سفتریاکسون و سفتازیدیم در این ردیف‌اند، اما طیف یکسانی ندارند؛ سفتازیدیم از اعضای دارای فعالیت ضدسودوموناسی است.'],['افزایش‌یافته','سفپیم و سفپیروم؛ ردیف آخر جدول'],['کارباپنم','ایمیپنم، ارتاپنم و دوریپنم در فهرست؛ هدف دیواره و مسئلهٔ مقاومت؛ فعالیت یک عضو را برای همه فرض نکن.'] ],
 'خانواده یکسان، طیف الزاماً یکسان نیست؛ برای جدول، نام و محور را با هم بخوان.',
 [('چرا ردیف وسیع، فعالیت یکسان همهٔ نام‌ها را ثابت نمی‌کند؟','اعضای یک نسل ممکن است از نظر فعالیت علیه یک عامل تفاوت داشته باشند. برای مثال، قرارگرفتن سفتریاکسون و سفتازیدیم در یک نسل به معنی فعالیت ضدسودوموناسیِ یکسان نیست.',['عضو','طیف','قید']),('هدف مشترک این گروه‌ها چیست؟','مهار ساخت دیواره؛ اما این شباهت مکانیسم، مقاومت و طیف یکسان را ثابت نمی‌کند.',['دیواره','تفاوت طیف','مقاومت'])])
A(2,'گلیکوپپتید، پلی‌پپتید و غشا',[10,12,13], 'وانکومایسین ساخت پپتیدوگلیکان را مهار می‌کند؛ پلی‌میکسین‌ها به غشا آسیب می‌زنند. دیواره و غشا دو ساختار متفاوت با هدف‌های دارویی متفاوت‌اند.',[
 ['وانکومایسین','ارتباط با انتهای D-Ala–D-Ala و مهار ساخت پپتیدوگلیکان؛ پوشش خارجیِ گرم منفی مانع دسترسی در توضیح منبع'],['تغییر هدف','D-Ala–D-Lac در شکل با کاهش اتصال دارو مقایسه شده؛ VanA و VanB برای مقاومت اکتسابی ذکر شده‌اند.'],['باسیتراسین','پلی‌پپتید با کاربرد موضعی در مثال‌های منبع؛ از گلیکوپپتید و بتالاکتام جداست.'],['پلی‌میکسین B و E','E همان کولیستین؛ اثر بر LPS/فسفولیپید و نفوذپذیری غشا در ادامهٔ متن'],['داروهای سل در فهرست','ایزونیازید، اتیونامید، اتامبوتول و سیکلوسرین در بحث ساختار دیوارهٔ مایکوباکتری؛ ریفامپین را در بخش RNA جدا بخوان.'],['دندان','انتروکوک فکالیس و بیوفیلم ریشه مثال منبع‌اند؛ رسیدگی به منبع و زمینه را با یک داروی ثابت یکی نکن.'] ],
 'وانکو و انتهای دیواره؛ پلی‌میکسین و غشا؛ یکسان نیستند.',
 [('تغییر D-Ala–D-Ala چرا مهم است؟','در شکل، تغییر انتهای هدف به کاهش اتصال وانکومایسین مرتبط می‌شود؛ مثال تغییر هدف دارویی است.',['انتهای هدف','اتصال','مقاومت']),('کولیستین چه ساختاری را هدف می‌گیرد و با وانکومایسین چه فرقی دارد؟','کولیستین با برهم‌زدن ساختار و نفوذپذیری غشای باکتری‌های گرم منفی اثر می‌کند. وانکومایسین به انتهای D-Ala–D-Ala پیش‌ساز پپتیدوگلیکان متصل می‌شود و ساخت دیواره را مهار می‌کند.',['کولیستین و غشا','وانکومایسین و دیواره'])])
A(3,'مهار پروتئین: زیرواحد ۳۰S',[13,14], 'آمینوگلیکوزیدها و تتراسایکلین‌ها هر دو به زیرواحد ۳۰S ریبوزوم اثر می‌کنند، اما مرحلهٔ مهارشده و چگونگی ورودشان به سلول یکسان نیست.',[
 ['آمینوگلیکوزید','استرپتومایسین، نئومایسین، کانامایسین، توبرامایسین، جنتامایسین، سیزومایسین، آمیکاسین و نتیلمایسین در متن'],['منشأها','استرپتومایسس و میکرومونوسپورا؛ برخی مشتق نیمه‌سنتزی‌اند.'],['مکانیسم','اتصال ۳۰S و اختلال پروتئین‌سازی؛ ورود انرژی‌وابسته؛ کاهش ورود در شرایط بی‌هوازی از محدودیت‌های مهم این گروه است.'],['همراهی','ورود دشوار در برخی کوکسی‌ها و منطق هم‌افزایی با داروی دیواره‌ای؛ به معنی ضرورت یک ترکیب برای همه نیست.'],['مقاومت','تغییر هدف، ورود کمتر، غیرفعال‌سازی آنزیمی و خروج بیشتر؛ این چهار سازوکار می‌توانند به‌تنهایی یا هم‌زمان وجود داشته باشند.'],['تتراسایکلین','تتراسایکلین، داکسی‌سایکلین و مینوسایکلین؛ جلوگیری از ورود آمینوآسیل tRNA به مجموعهٔ ریبوزومی؛ باکتریواستاتیک در منبع'],['نمونهٔ کاربرد','عوامل درون‌سلولی/تنفسی، آکنه و برخی عفونت‌ها در جزوه؛ نام کاربرد، الگوریتم تجویز نیست.'] ],
 '۳۰S: آمینوگلیکوزید و تتراسایکلین؛ ورود به سلول را هم توضیح بده.',
 [('آمینوگلیکوزید و تتراسایکلین را مقایسه کنید.','هر دو به ۳۰S مربوط‌اند؛ در متن اولی با اتصال و اختلال پروتئین‌سازی و ورود انرژی‌وابسته، دومی با ممانعت ورود tRNA و اثر مهاری شرح داده می‌شود.',['هدف مشترک','مراحل متفاوت','ورود']),('چهار مسیر مقاومت را بنویسید.','تغییر هدف، کاهش ورود، افزایش خروج و غیرفعال‌سازی آنزیمی.',['چهار مسیر'])])
A(3,'مهار پروتئین: زیرواحد ۵۰S',[13,15], 'کلرامفنیکل، ماکرولیدها و کلیندامایسین از داروهای مؤثر بر زیرواحد ۵۰S هستند. هدف مشترک به معنای طیف، عارضه و کاربرد یکسان نیست.',[
 ['کلرامفنیکل','مهار فعالیت پپتیدیل‌ترانسفراز و ساخت پروتئین؛ استیل‌ترانسفراز می‌تواند دارو را غیرفعال کند. سمیت مغز استخوان و آنمی آپلاستیک از عوارض مهم مطرح در درس‌اند.'],['ماکرولید','اریترومایسین، آزیترومایسین و کلاریترومایسین؛ اتصال به ۵۰S و توقف طویل‌شدن در توضیح'],['کلیندامایسین','لینکوزآمید؛ ۵۰S؛ نام کاربرد دندان‌پزشکی و خطر کولیت دیفیسیل در جدول بعدی'],['استرپتوگرامین','ترکیب A و B، هم‌افزایی؛ کوئینوپریستین–دالفوپریستین در منبع'],['اگزازولیدینون','در فهرست ۵۰S و شکل هدف‌ها؛ لاینزولید مثال شکل است.'],['نکتهٔ مطالعه','نام گروه، هدف، یک محدودیت/عارضه را کنار هم یاد بگیر، نه فهرست مجزای نام‌ها.'] ],
 '۵۰S: کلرامفنیکل، ماکرولید، کلیندامایسین و گروه‌های دیگر؛ عارضه را جدا وصل کن.',
 [('سه خانوادهٔ مهم ۵۰S را نام ببرید.','کلرامفنیکل، ماکرولید و لینکوزآمید مانند کلیندامایسین؛ استرپتوگرامین و اگزازولیدینون هم در منبع‌اند.',['نام','مثال','هدف']),('چرا هدف مشترک، جایگزینی خودکار را توجیه نمی‌کند؟','طیف، عوارض، مقاومت و زمینهٔ عامل تفاوت دارند؛ برای مثال خطر مغز استخوان و کولیت دو محدودیت جدا هستند.',['طیف','عارضه','مقاومت'])])
A(3,'DNA، RNA و مسیر فولات',[16], 'کینولون‌ها به آنزیم‌های دی‌ان‌ای، ریفامپین به رونویسی و سولفونامیدها و تری‌متوپریم به مسیر فولات اثر می‌کنند. این هدف‌ها را با مهار دیواره و ریبوزوم مقایسه کن.',[
 ['کینولون','مهار DNA ژیراز/توپوایزومراز II یا IV؛ نالیدیکسیک اسید و فلوروکینولون‌ها مانند سیپروفلوکساسین، لووفلوکساسین و موکسی‌فلوکساسین در متن'],['ریفامپین/ریفابوتین','RNA پلیمراز وابسته به DNA و مهار رونویسی؛ با هدف دیواره اشتباه نشود.'],['مترونیدازول','در بخش اسید نوکلئیک، برای بی‌هوازی‌ها و برخی تک‌یاخته‌ها مطرح؛ ارتباط دندانی آبسهٔ بی‌هوازی در جزوه'],['سولفونامید','رقابت با PABA و مهار مسیر ساخت فولات میکروبی'],['تری‌متوپریم','مهار دی‌هیدروفولات ردوکتاز؛ همراه سولفامتوکسازول برای مهار پیاپی دو مرحله'],['پیامد','کاهش فراهم‌شدن پیش‌سازهای لازم برای ساخت مولکول‌ها؛ مسیر فولات را با دیواره و ریبوزوم جدا نگه دار.'] ],
 'کینولون DNA؛ ریفامپین RNA؛ دو داروی فولات، دو گام پیاپی.',
 [('چرا تری‌متوپریم و سولفامتوکسازول کنار هم مطرح‌اند؟','دو مرحلهٔ متفاوت مسیر فولات را مهار می‌کنند؛ هم‌افزایی پیاپی، منطق شرح منبع است.',['دو هدف','فولات','پیاپی']),('ریفامپین و کینولون را مقایسه کنید.','اولی رونویسی با RNA پلیمراز، دومی آنزیم‌های تنظیم DNA و همانندسازی را هدف می‌گیرد.',['RNA','DNA','آنزیم'])])
A(4,'منشأ و مکانیسم مقاومت',[3,6,17], 'مقاومت ممکن است با جهش یا دریافت ژن ایجاد شود. محصول این تغییر می‌تواند هدف دارو را عوض کند، ورود آن را کاهش دهد، خروجش را افزایش دهد یا دارو را غیرفعال کند.',[
 ['جهش','تغییر در مادهٔ ژنتیکی می‌تواند هدف یا تنظیم بیان را عوض کند؛ قطع درمان را علت قطعی مستقیم هر جهش ندان.'],['پلاسمید','حمل و انتقال ژن‌های مقاومت؛ دریافت ویژگی با تغییر خودبه‌خودی توالی یک مسیر واحد نیست.'],['نفوذ و پمپ','ورود کمتر از پوشش یا پورین و خروج بیشتر با پمپ'],['آنزیم','تخریب یا تغییر دارو؛ بتالاکتاماز نمونهٔ کلیدی'],['ESBL و MBL','ESBL به بتالاکتامازِ دارای طیف گسترده و MBL به متالوبتالاکتاماز اشاره دارد. نام آنزیم، با الگوی مقاومت مرتبط است؛ همهٔ این آنزیم‌ها داروهای یکسانی را تخریب نمی‌کنند.'],['NDM-1','متالوبتالاکتامازی که اهمیت انتقال ژن مقاومت میان باکتری‌ها را نشان می‌دهد.'] ],
 'مقاومت از جهش یا دریافت ژن پدید می‌آید؛ با تغییر هدف، ورود کمتر، خروج بیشتر یا غیرفعال‌سازی دارو اثر می‌کند.',
 [('منشأ و مکانیسم مقاومت را تفکیک کنید.','جهش/انتقال، راه پیدایش یا دریافت ویژگی‌اند؛ آنزیم، هدف عوض‌شده، نفوذ کم و خروج زیاد، چگونگی اثر ویژگی را شرح می‌دهند.',['منشأ','اثر','مثال']),('چرا ژن قابل‌انتقال اهمیت بیمارستانی دارد؟','ویژگی می‌تواند بین جمعیت‌ها گسترش یابد؛ کنترل فقط به درمان یک فرد محدود نمی‌ماند.',['انتقال','جمعیت','کنترل'])])
A(4,'جدول داروهای دندانیِ خود جزوه',[17,18], 'در مرور داروهای مطرح در دندان‌پزشکی، نام هر دارو را کنار هدف مولکولی و محدودیت مهمش بنویس. جدول زیر برای یادگیری این ارتباط‌هاست.',[
 ['آموکسی‌سیلین','دیواره؛ برخی گرم مثبت/منفی؛ آبسه، پریودنتیت و پیشگیری در جدول؛ مقاومت رو به افزایش به‌عنوان نکته'],['آموکسی‌کلاو','دیواره و مهار آنزیم؛ عفونت شدید/نکروز فک در جدول؛ قید مقاومت و زمینه مهم است.'],['مترونیدازول','DNA و بی‌هوازی؛ همراهی در آبسه/ریشه و لثه در منبع'],['کلیندامایسین','پروتئین؛ گرم مثبت و بی‌هوازی؛ حساسیت به پنی‌سیلین در مثال؛ هشدار کولیت دیفیسیل در جدول'],['آزیترومایسین','پروتئین؛ التهاب لثه/حساسیت در مثال؛ نیمه‌عمر طولانی‌تر در متن'],['سفوروکسیم / سفیکسیم','دیواره؛ نسل دوم/سوم؛ عفونت مقاوم و سینوس‌لیفت در جدول'],['تتراسایکلین / داکسی‌سایکلین','پروتئین و نقش ضدالتهابی در بحث پریودنتال؛ مصرف موضعی هم ذکر شده است.'],['نام‌های جدید منبع','سفیدروکول، سفتازیدیم–آویباکتام، ایمیپنم–رلباکتام، مروپنم–وبروباکتام و لفامولین؛ این نام‌ها را با خانواده و هدف اثرشان مرور کن.'] ],
 'برای هر ردیف: نام، هدف، دامنه و قید؛ نام دارو به‌تنهایی جواب کامل نیست.',
 [('جدول را چگونه برای امتحان تشریحی خلاصه می‌کنید؟','برای هر گروه هدف مولکولی و یک ویژگی دامنه/محدودیت می‌نویسم؛ مثال کلیندامایسین ۵۰S و خطر کولیت در متن.',['نام','هدف','محدودیت']),('چرا داروی جدید لزوماً همهٔ مقاومت‌ها را حل نمی‌کند؟','عامل و مکانیسم مقاومت متفاوت‌اند؛ مهارکننده یا خانوادهٔ تازه هدف و دامنهٔ مشخص دارد و نیاز به شناخت جدایه باقی می‌ماند.',['عامل','مکانیسم','دامنه'])])
A(4,'وبا، کمپیلوباکتر و هلیکوباکتر',[19,20,21,22,23,24], 'وبا بیشتر با از دست رفتن آب و الکترولیت، کمپیلوباکتر با التهاب روده و هلیکوباکتر پیلوری با بیماری‌های معده شناخته می‌شوند. این بخش، تظاهرهای شاخص هر کدام را مرور می‌کند.',[
 ['وبا','ویبریو کلرا O1؛ حمل بی‌علامت تا اسهال شدید؛ اسهال آبکی/استفراغ و مدفوع آب‌برنجی در اسلاید'],['پیامد عمده','از دست رفتن آب و الکترولیت و شوک کم‌حجمی؛ اولویت جبران مایع در این درس، دارو در درجهٔ دوم'],['کمپیلوباکتر','ژژونی، کلی و اوپسالینسیس؛ انتریت، اسهال، تهوع، تب و درد شکم'],['گیلن‌باره','اسلاید جدا ضعف عضلات اندام و تنه/قفسهٔ سینه را نام می‌برد؛ جزئیات مکانیسم در این فایل ارائه نشده است.'],['هلیکوباکتر پیلوری','همراهی با گاستریت، زخم معده/دوازدهه، آدنوکارسینوم و لنفوم MALT؛ درصدها آمار همان اسلایدند.'],['گونه‌های دیگر','سینادی و فنلیا با استقرار روده و پروکتیت/انتریت در متن؛ جداسازی از پستانداران نیز ذکر شده است.'],['ترکیب در اسلاید آخر','مهارکنندهٔ پمپ پروتون با آنتی‌بیوتیک‌های نام‌برده مانند آموکسی‌سیلین، کلاریترومایسین و مترونیدازول؛ مدت متن راهنمای به‌روز نیست.'] ],
 'وبا و مایع؛ کمپیلوباکتر و انتریت؛ هلیکوباکتر و معده/MALT.',
 [('چرا اولویت در شرح وبا مایع است؟','خطر فوریِ مطرح‌شده، کمبود حجم و الکترولیت است؛ حذف عامل و اصلاح پیامد دو هدف متفاوت‌اند.',['حجم','الکترولیت','دو هدف']),('ارتباط‌های هلیکوباکتر در فایل چیست؟','گاستریت، زخم پپتیک و همراهی با آدنوکارسینوم و MALT؛ این‌ها احتمال و ارتباط‌اند، نه پیامد اجباری هر حمل.',['گاستریت','زخم','دو بدخیمی','قید'])])
source=[Q('مهارکننده‌های بتالاکتاماز را نام ببرید.','کلاوولانات، سولباکتام و تازوباکتام از مهارکننده‌های مطرح در این درس‌اند. آموکسی‌کلاو ترکیب آموکسی‌سیلین با کلاوولانات و پیپراسیلین–تازوباکتام ترکیب آنتی‌بیوتیک با مهارکننده است؛ آمپی‌سیلین به‌تنهایی مهارکنندهٔ بتالاکتاماز نیست.',['نام مهارکننده‌ها','دارو در برابر ترکیب','نقش هر جزء'],[8],'سؤال ترم قبل در جزوه')]
mixed=[Q('یک دارو را در سه محور هدف، طیف و مقاومت توصیف کنید.','هدف ساختار/مسیر مولکولی است؛ طیف گروه عوامل حساس؛ مقاومت ویژگی‌ای است که اثر را کم می‌کند. مثال بتالاکتامِ دیواره‌ای با آنزیم هیدرولیزکننده، هر سه محور را جدا می‌کند.',['سه محور','مثال'],[5,7,8,17]),Q('تغییر هدف، آنزیم و پمپ را مقایسه کنید.','هدف عوض‌شده اتصال را کم می‌کند، آنزیم دارو را غیرفعال می‌کند و پمپ غلظت داخل سلول را کم می‌کند؛ مثال‌ها در وانکومایسین، بتالاکتام و چند گروه دیگر آمده‌اند.',['سه سازوکار','مثال'],[12,14,17]),Q('۳۰S، ۵۰S، DNA و RNA را با گروه دارویی جفت کنید.','۳۰S آمینوگلیکوزید/تتراسایکلین؛ ۵۰S ماکرولید/کلرامفنیکل/کلیندامایسین؛ DNA کینولون؛ RNA ریفامپین.',['چهار هدف','نمونهٔ درست'],[13,14,15,16])]
finish('استاد هاشمی','hashemi','سوم','جلسه‌های اول و چهارم، و اسلایدهای گوارشی',[([1,2],'جلد و فهرست',[]),([3,4,5,6],'مقدمه، تاریخچه، اصطلاح‌ها، MTT و هم‌افزایی',[1]),([6,7],'آزمون و شکل هدف‌های مولکولی',[2]),([7,8],'بتالاکتام و سؤال اصلی',[3]),([9,10],'تمام ردیف‌های جدول سفالوسپورین و کارباپنم',[4]),([11],'فهرست',[]),([12,13],'وانکومایسین، تغییر هدف، پلی‌پپتید و غشا',[5]),([13,14],'۳۰S و چهار مسیر مقاومت',[6]),([15],'همهٔ گروه‌های ۵۰S',[7]),([16],'DNA، RNA و فولات',[8]),([17,18],'مقاومت، تمام ردیف‌های جدول دندان و نام‌های جدید',[9,10]),([19,20,21,22,23,24],'همهٔ اسلایدهای وبا، کمپیلوباکتر، گیلن‌باره و هلیکوباکتر',[11])],mixed,source)
